package com.alchemiser;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(AlchemiserConfig.GROUP)
public interface AlchemiserConfig extends Config
{
	String GROUP = "alchemiser";
	String KEY_STACK_VALUE = "stackValue";
	String KEY_IGNORE_UNTRADABLES = "ignoreUntradables";
	// Stored via ConfigManager directly (CSV of item IDs), not exposed as a @ConfigItem
	String KEY_IGNORED_ITEMS = "ignoredItems";
	// Stored via ConfigManager directly, toggled by the in-bank button
	String KEY_BANK_SORT = "bankSort";

	@ConfigItem(
		keyName = KEY_STACK_VALUE,
		name = "Stack value",
		description = "Sort and display by the high alch value of the whole stack instead of a single item"
	)
	default boolean stackValue()
	{
		return false;
	}

	@ConfigItem(
		keyName = KEY_IGNORE_UNTRADABLES,
		name = "Ignore untradeables",
		description = "Hide untradeable items from the list"
	)
	default boolean ignoreUntradables()
	{
		return false;
	}
}

package com.alchemiser;

import java.awt.BorderLayout;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.image.BufferedImage;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;
import java.util.function.ToLongFunction;
import java.util.stream.Collectors;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.ImageIcon;
import javax.swing.JButton;
import javax.swing.JCheckBox;
import javax.swing.JLabel;
import javax.swing.JMenuItem;
import javax.swing.JPanel;
import javax.swing.JPopupMenu;
import javax.swing.JToggleButton;
import javax.swing.SwingConstants;
import javax.swing.border.EmptyBorder;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.DynamicGridLayout;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.ui.components.IconTextField;
import net.runelite.client.util.AsyncBufferedImage;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.QuantityFormatter;
import net.runelite.client.util.SwingUtil;

class AlchemiserPanel extends PluginPanel
{
	private static final int ITEM_ICON_WIDTH = 36;
	private static final int ITEM_ICON_HEIGHT = 32;

	private static final ImageIcon IGNORE_ICON;
	private static final ImageIcon IGNORE_HOVER_ICON;
	private static final ImageIcon RESTORE_ICON;
	private static final ImageIcon RESTORE_HOVER_ICON;

	static
	{
		final BufferedImage ignoreImg = ImageUtil.loadImageResource(AlchemiserPanel.class, "ignore.png");
		IGNORE_ICON = new ImageIcon(ignoreImg);
		IGNORE_HOVER_ICON = new ImageIcon(ImageUtil.alphaOffset(ignoreImg, 0.6f));

		final BufferedImage restoreImg = ImageUtil.loadImageResource(AlchemiserPanel.class, "restore.png");
		RESTORE_ICON = new ImageIcon(restoreImg);
		RESTORE_HOVER_ICON = new ImageIcon(ImageUtil.alphaOffset(restoreImg, 0.6f));
	}

	private final AlchemiserPlugin plugin;
	private final ItemManager itemManager;

	private final IconTextField searchBar = new IconTextField();
	private final JToggleButton valueModeToggle = new JToggleButton("Item value");
	private final JCheckBox ignoreUntradablesCheckbox = new JCheckBox("Ignore untradeables");
	private final JCheckBox showIgnoredCheckbox = new JCheckBox("Show ignored only");
	private final JPanel listPanel = new JPanel();
	private final JLabel emptyLabel = new JLabel("", SwingConstants.CENTER);

	private List<BankItem> items = Collections.emptyList();

	AlchemiserPanel(AlchemiserPlugin plugin, ItemManager itemManager)
	{
		this.plugin = plugin;
		this.itemManager = itemManager;

		setLayout(new BorderLayout(0, 8));
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		final JPanel controls = new JPanel(new DynamicGridLayout(0, 1, 0, 4));
		controls.setBackground(ColorScheme.DARK_GRAY_COLOR);

		searchBar.setIcon(IconTextField.Icon.SEARCH);
		searchBar.setPreferredSize(new Dimension(0, 30));
		searchBar.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		searchBar.setHoverBackgroundColor(ColorScheme.DARK_GRAY_HOVER_COLOR);
		searchBar.getDocument().addDocumentListener(new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent e)
			{
				rebuild();
			}

			@Override
			public void removeUpdate(DocumentEvent e)
			{
				rebuild();
			}

			@Override
			public void changedUpdate(DocumentEvent e)
			{
				rebuild();
			}
		});
		controls.add(searchBar);

		valueModeToggle.setToolTipText("Switch between the high alch value of a single item and of the whole stack");
		valueModeToggle.setFocusPainted(false);
		valueModeToggle.addItemListener(e ->
		{
			updateToggleText();
			plugin.updateStackValue(valueModeToggle.isSelected());
		});
		controls.add(valueModeToggle);

		ignoreUntradablesCheckbox.setBackground(ColorScheme.DARK_GRAY_COLOR);
		ignoreUntradablesCheckbox.addItemListener(e ->
			plugin.updateIgnoreUntradables(ignoreUntradablesCheckbox.isSelected()));
		controls.add(ignoreUntradablesCheckbox);

		showIgnoredCheckbox.setBackground(ColorScheme.DARK_GRAY_COLOR);
		showIgnoredCheckbox.setToolTipText("Only show items on the ignore list, so they can be restored");
		showIgnoredCheckbox.addItemListener(e -> rebuild());
		controls.add(showIgnoredCheckbox);

		add(controls, BorderLayout.NORTH);

		listPanel.setLayout(new DynamicGridLayout(0, 1, 0, 4));
		listPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		add(listPanel, BorderLayout.CENTER);

		emptyLabel.setFont(FontManager.getRunescapeSmallFont());
		emptyLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

		rebuild();
	}

	void setControls(boolean stackValue, boolean ignoreUntradables)
	{
		// setSelected only fires the item listener when the state actually changes,
		// so syncing from config does not loop back into another config write
		valueModeToggle.setSelected(stackValue);
		updateToggleText();
		ignoreUntradablesCheckbox.setSelected(ignoreUntradables);
	}

	void setItems(List<BankItem> items)
	{
		this.items = items;
		rebuild();
	}

	void rebuild()
	{
		listPanel.removeAll();

		final boolean stackValue = valueModeToggle.isSelected();
		final boolean ignoreUntradables = ignoreUntradablesCheckbox.isSelected();
		final boolean ignoredOnly = showIgnoredCheckbox.isSelected();
		final String search = searchBar.getText().trim().toLowerCase(Locale.ROOT);

		final ToLongFunction<BankItem> valueOf = stackValue ? BankItem::getStackHaValue : BankItem::getHaPrice;
		final List<BankItem> shown = items.stream()
			.filter(item -> plugin.isIgnored(item.getId()) == ignoredOnly)
			.filter(item -> !ignoreUntradables || item.isTradeable())
			.filter(item -> search.isEmpty() || item.getName().toLowerCase(Locale.ROOT).contains(search))
			.sorted(Comparator.comparingLong(valueOf).reversed().thenComparing(BankItem::getName))
			.collect(Collectors.toList());

		if (shown.isEmpty())
		{
			if (items.isEmpty())
			{
				emptyLabel.setText("Open your bank to load its contents.");
			}
			else if (ignoredOnly)
			{
				emptyLabel.setText("No ignored items match.");
			}
			else
			{
				emptyLabel.setText("No items match the current filters.");
			}
			listPanel.add(emptyLabel);
		}
		else
		{
			for (BankItem item : shown)
			{
				listPanel.add(buildRow(item, stackValue, valueOf.applyAsLong(item), ignoredOnly));
			}
		}

		listPanel.revalidate();
		listPanel.repaint();
	}

	private void updateToggleText()
	{
		valueModeToggle.setText(valueModeToggle.isSelected() ? "Stack value" : "Item value");
	}

	private JPanel buildRow(BankItem item, boolean stackValue, long value, boolean ignoredView)
	{
		final JPanel row = new JPanel(new BorderLayout(6, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(new EmptyBorder(4, 6, 4, 6));

		final JLabel iconLabel = new JLabel();
		iconLabel.setPreferredSize(new Dimension(ITEM_ICON_WIDTH, ITEM_ICON_HEIGHT));
		final AsyncBufferedImage icon = itemManager.getImage(item.getId(), item.getQuantity(), item.getQuantity() > 1);
		icon.addTo(iconLabel);
		row.add(iconLabel, BorderLayout.WEST);

		final JPanel textPanel = new JPanel();
		textPanel.setLayout(new BoxLayout(textPanel, BoxLayout.Y_AXIS));
		textPanel.setBackground(ColorScheme.DARKER_GRAY_COLOR);

		final JLabel nameLabel = new JLabel(item.getName());
		nameLabel.setFont(FontManager.getRunescapeSmallFont());
		nameLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

		String valueText = QuantityFormatter.quantityToStackSize(value) + " gp";
		if (stackValue && item.getQuantity() > 1)
		{
			valueText += " - " + QuantityFormatter.quantityToStackSize(item.getHaPrice()) + " ea";
		}
		final JLabel valueLabel = new JLabel(valueText);
		valueLabel.setFont(FontManager.getRunescapeSmallFont());
		valueLabel.setForeground(ColorScheme.GRAND_EXCHANGE_ALCH);

		textPanel.add(nameLabel);
		textPanel.add(Box.createVerticalStrut(2));
		textPanel.add(valueLabel);
		row.add(textPanel, BorderLayout.CENTER);

		final JButton ignoreButton = new JButton(ignoredView ? RESTORE_ICON : IGNORE_ICON);
		SwingUtil.removeButtonDecorations(ignoreButton);
		ignoreButton.setRolloverIcon(ignoredView ? RESTORE_HOVER_ICON : IGNORE_HOVER_ICON);
		ignoreButton.setPreferredSize(new Dimension(18, ITEM_ICON_HEIGHT));
		ignoreButton.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		ignoreButton.setToolTipText(ignoredView ? "Remove from ignore list" : "Add to ignore list");
		ignoreButton.addActionListener(e -> plugin.setIgnored(item.getId(), !ignoredView));
		row.add(ignoreButton, BorderLayout.EAST);

		final JPopupMenu popup = new JPopupMenu();
		final JMenuItem ignoreMenuItem = new JMenuItem(ignoredView ? "Remove from ignore list" : "Add to ignore list");
		ignoreMenuItem.addActionListener(e -> plugin.setIgnored(item.getId(), !ignoredView));
		popup.add(ignoreMenuItem);
		row.setComponentPopupMenu(popup);
		iconLabel.setInheritsPopupMenu(true);
		textPanel.setInheritsPopupMenu(true);
		nameLabel.setInheritsPopupMenu(true);
		valueLabel.setInheritsPopupMenu(true);

		row.setToolTipText("<html>" + item.getName()
			+ "<br>HA: " + QuantityFormatter.formatNumber(item.getHaPrice()) + " gp each"
			+ "<br>Stack: " + QuantityFormatter.formatNumber(item.getStackHaValue()) + " gp</html>");

		return row;
	}
}

package com.alchemiser;

import com.google.common.base.Strings;
import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.ScriptID;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.SpriteID;
import net.runelite.api.widgets.JavaScriptCallback;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetPositionMode;
import net.runelite.api.widgets.WidgetType;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.Text;

@Slf4j
@PluginDescriptor(
	name = "Alchemiser",
	description = "Displays bank items in a side panel sorted by high alchemy value",
	tags = {"alch", "high alch", "bank", "alchemy"}
)
public class AlchemiserPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ConfigManager configManager;

	@Inject
	private AlchemiserConfig config;

	private AlchemiserPanel panel;
	private NavigationButton navButton;
	// Mutated on the EDT, also read from the client thread by the bank sort
	private final Set<Integer> ignoredItemIds = ConcurrentHashMap.newKeySet();
	// Only touched on the client thread
	private Widget bankSortButton;
	private boolean bankSortEnabled;

	@Override
	protected void startUp() throws Exception
	{
		loadIgnoredItems();
		bankSortEnabled = Boolean.parseBoolean(
			configManager.getConfiguration(AlchemiserConfig.GROUP, AlchemiserConfig.KEY_BANK_SORT));
		panel = new AlchemiserPanel(this, itemManager);
		panel.setControls(config.stackValue(), config.ignoreUntradables());

		final BufferedImage icon = ImageUtil.loadImageResource(getClass(), "icon.png");
		navButton = NavigationButton.builder()
			.tooltip("Alchemiser")
			.icon(icon)
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		// Populate from the cached bank container if one exists (e.g. plugin toggled on mid-session),
		// and add the bank button if the bank is already open
		clientThread.invoke(() ->
		{
			ItemContainer bank = client.getItemContainer(InventoryID.BANK);
			if (bank != null)
			{
				snapshotBank(bank);
			}
			createBankSortButton();
			layoutBank();
		});
	}

	@Override
	protected void shutDown() throws Exception
	{
		clientToolbar.removeNavigation(navButton);
		navButton = null;
		panel = null;

		clientThread.invoke(() ->
		{
			if (bankSortButton != null)
			{
				bankSortButton.setHidden(true);
				bankSortButton = null;
			}
			// Rebuild the bank to undo our sorting; by the time this runs the plugin is
			// unsubscribed, so the rebuild lays items out in their natural order
			layoutBank();
		});
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() == InventoryID.BANK)
		{
			snapshotBank(event.getItemContainer());
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!AlchemiserConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}

		final boolean stackValue = config.stackValue();
		final boolean ignoreUntradables = config.ignoreUntradables();
		SwingUtilities.invokeLater(() ->
		{
			if (panel != null)
			{
				panel.setControls(stackValue, ignoreUntradables);
				panel.rebuild();
			}
		});

		if (AlchemiserConfig.KEY_STACK_VALUE.equals(event.getKey())
			|| AlchemiserConfig.KEY_IGNORED_ITEMS.equals(event.getKey()))
		{
			// Sort mode or ignore list changed; re-sort the bank if it is open and sorting is on
			clientThread.invoke(this::layoutBank);
		}
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == InterfaceID.BANKMAIN)
		{
			createBankSortButton();
		}
	}

	@Subscribe
	public void onScriptPostFired(ScriptPostFired event)
	{
		if (event.getScriptId() == ScriptID.BANKMAIN_BUILD && bankSortEnabled)
		{
			sortBankItems();
		}
	}

	private void createBankSortButton()
	{
		Widget frame = client.getWidget(InterfaceID.Bankmain.FRAME);
		if (frame == null)
		{
			return;
		}

		Widget button = frame.createChild(-1, WidgetType.GRAPHIC);
		button.setOriginalWidth(20);
		button.setOriginalHeight(20);
		// Sit just left of the close button in the top-right corner
		button.setPos(32, 7, WidgetPositionMode.ABSOLUTE_RIGHT, WidgetPositionMode.ABSOLUTE_TOP);
		button.setSpriteId(bankSortEnabled ? SpriteID.Magicon.HIGH_LEVEL_ALCHEMY : SpriteID.Magicoff.HIGH_LEVEL_ALCHEMY);
		button.setAction(0, "Toggle high alch sort");
		button.setHasListener(true);
		button.setNoClickThrough(true);
		button.setOnOpListener((JavaScriptCallback) e -> toggleBankSort());
		button.revalidate();
		bankSortButton = button;
	}

	private void toggleBankSort()
	{
		bankSortEnabled = !bankSortEnabled;
		configManager.setConfiguration(AlchemiserConfig.GROUP, AlchemiserConfig.KEY_BANK_SORT, bankSortEnabled);
		if (bankSortButton != null)
		{
			bankSortButton.setSpriteId(bankSortEnabled ? SpriteID.Magicon.HIGH_LEVEL_ALCHEMY : SpriteID.Magicoff.HIGH_LEVEL_ALCHEMY);
		}
		layoutBank();
	}

	// Re-runs the bank build script, which lays items out in natural order and then
	// fires ScriptPostFired, where we re-sort if enabled. Must be on the client thread.
	private void layoutBank()
	{
		Widget itemsContainer = client.getWidget(InterfaceID.Bankmain.ITEMS);
		if (itemsContainer == null || itemsContainer.isHidden())
		{
			return;
		}

		Object[] scriptArgs = itemsContainer.getOnInvTransmitListener();
		if (scriptArgs != null)
		{
			client.runScript(scriptArgs);
		}
	}

	// Permutes the visible bank item widgets into HA-value order, reusing the exact
	// slot positions the game laid out so spacing stays correct. Ignored items are
	// moved below the rest, separated by a two-row gap
	private void sortBankItems()
	{
		Widget itemsContainer = client.getWidget(InterfaceID.Bankmain.ITEMS);
		if (itemsContainer == null)
		{
			return;
		}

		List<Widget> keptWidgets = new ArrayList<>();
		List<Widget> ignoredWidgets = new ArrayList<>();
		for (Widget child : itemsContainer.getDynamicChildren())
		{
			if (child.isSelfHidden() || child.getItemId() <= 0)
			{
				continue;
			}

			if (ignoredItemIds.contains(itemManager.canonicalize(child.getItemId())))
			{
				ignoredWidgets.add(child);
			}
			else
			{
				keptWidgets.add(child);
			}
		}

		final List<int[]> slotPositions = new ArrayList<>();
		for (Widget w : keptWidgets)
		{
			slotPositions.add(new int[]{w.getOriginalX(), w.getOriginalY()});
		}
		for (Widget w : ignoredWidgets)
		{
			slotPositions.add(new int[]{w.getOriginalX(), w.getOriginalY()});
		}
		slotPositions.sort(Comparator.<int[]>comparingInt(p -> p[1]).thenComparingInt(p -> p[0]));

		final boolean stackValue = config.stackValue();
		final Comparator<Widget> byValueDesc = Comparator.comparingLong((Widget w) -> haValue(w, stackValue)).reversed();
		keptWidgets.sort(byValueDesc);
		ignoredWidgets.sort(byValueDesc);

		for (int i = 0; i < keptWidgets.size(); i++)
		{
			Widget w = keptWidgets.get(i);
			int[] pos = slotPositions.get(i);
			w.setOriginalX(pos[0]);
			w.setOriginalY(pos[1]);
			w.revalidate();
		}

		if (ignoredWidgets.isEmpty())
		{
			return;
		}

		// Derive the grid geometry from the game's own layout: distinct columns, and
		// the vertical pitch between rows (falls back to the standard 36px)
		final List<Integer> columns = slotPositions.stream()
			.map(p -> p[0])
			.distinct()
			.sorted()
			.collect(Collectors.toList());
		final List<Integer> rows = slotPositions.stream()
			.map(p -> p[1])
			.distinct()
			.sorted()
			.collect(Collectors.toList());
		final int rowPitch = rows.size() >= 2 ? rows.get(1) - rows.get(0) : 36;

		final int lastKeptY = keptWidgets.isEmpty()
			? rows.get(0) - rowPitch
			: slotPositions.get(keptWidgets.size() - 1)[1];
		// Next row after the kept section, plus a two-row spacer gap
		final int ignoredStartY = lastKeptY + 3 * rowPitch;

		int lastIgnoredY = ignoredStartY;
		for (int i = 0; i < ignoredWidgets.size(); i++)
		{
			Widget w = ignoredWidgets.get(i);
			int x = columns.get(i % columns.size());
			int y = ignoredStartY + (i / columns.size()) * rowPitch;
			lastIgnoredY = y;
			w.setOriginalX(x);
			w.setOriginalY(y);
			w.revalidate();
		}

		// Extend the scroll area so the pushed-down ignored section stays reachable
		final int neededHeight = lastIgnoredY + rowPitch;
		if (itemsContainer.getScrollHeight() < neededHeight)
		{
			itemsContainer.setScrollHeight(neededHeight);
			final int scrollY = itemsContainer.getScrollY();
			client.runScript(ScriptID.UPDATE_SCROLLBAR, InterfaceID.Bankmain.SCROLLBAR, InterfaceID.Bankmain.ITEMS, scrollY);
		}
	}

	private long haValue(Widget itemWidget, boolean stackValue)
	{
		// Canonicalize so bank placeholders are valued as the real item
		final int canonicalId = itemManager.canonicalize(itemWidget.getItemId());
		final long haPrice = itemManager.getItemComposition(canonicalId).getHaPrice();
		return stackValue ? haPrice * itemWidget.getItemQuantity() : haPrice;
	}

	// Must be called on the client thread
	private void snapshotBank(ItemContainer bank)
	{
		final List<BankItem> items = new ArrayList<>();
		for (Item item : bank.getItems())
		{
			final int id = item.getId();
			final int quantity = item.getQuantity();
			// quantity <= 0 filters bank placeholders
			if (id <= 0 || quantity <= 0 || id == ItemID.BANK_FILLER)
			{
				continue;
			}

			final ItemComposition composition = itemManager.getItemComposition(id);
			items.add(new BankItem(id, quantity, composition.getName(), composition.getHaPrice(), composition.isTradeable()));
		}

		SwingUtilities.invokeLater(() ->
		{
			if (panel != null)
			{
				panel.setItems(items);
			}
		});
	}

	boolean isIgnored(int itemId)
	{
		return ignoredItemIds.contains(itemId);
	}

	void setIgnored(int itemId, boolean ignored)
	{
		final boolean changed = ignored ? ignoredItemIds.add(itemId) : ignoredItemIds.remove(itemId);
		if (!changed)
		{
			return;
		}

		// Persisting fires ConfigChanged, which rebuilds the panel
		configManager.setConfiguration(AlchemiserConfig.GROUP, AlchemiserConfig.KEY_IGNORED_ITEMS,
			ignoredItemIds.stream().map(String::valueOf).collect(Collectors.joining(",")));
	}

	private void loadIgnoredItems()
	{
		ignoredItemIds.clear();
		final String csv = configManager.getConfiguration(AlchemiserConfig.GROUP, AlchemiserConfig.KEY_IGNORED_ITEMS);
		if (Strings.isNullOrEmpty(csv))
		{
			return;
		}

		for (String id : Text.fromCSV(csv))
		{
			try
			{
				ignoredItemIds.add(Integer.parseInt(id));
			}
			catch (NumberFormatException e)
			{
				log.debug("Ignoring malformed ignored item id: {}", id);
			}
		}
	}

	void updateStackValue(boolean stackValue)
	{
		configManager.setConfiguration(AlchemiserConfig.GROUP, AlchemiserConfig.KEY_STACK_VALUE, stackValue);
	}

	void updateIgnoreUntradables(boolean ignoreUntradables)
	{
		configManager.setConfiguration(AlchemiserConfig.GROUP, AlchemiserConfig.KEY_IGNORE_UNTRADABLES, ignoreUntradables);
	}

	@Provides
	AlchemiserConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(AlchemiserConfig.class);
	}
}

